docs = ["hello world hello", "world bigdata", "hello bigdata world", "bigdata hello"]
R = 3
def mh(key, n):
    h = 0
    for ch in key:
        h = (h * 31 + ord(ch)) & 0x7fffffff
    return h % n
pairs = []
for line in docs:
    for w in line.lower().split():
        pairs.append((w, 1))
map_out = len(pairs)
buckets = {r: [] for r in range(R)}
for k, v in pairs:
    buckets[mh(k, R)].append((k, v))
shuffle_no_combiner = sum(len(b) for b in buckets.values())
combined = {}
for k, v in pairs:
    p = mh(k, R)
    combined[(p, k)] = combined.get((p, k), 0) + v
shuffle_with_combiner = len(combined)
print(f"map output kv: {map_out}")
print(f"shuffle kv without combiner: {shuffle_no_combiner}")
print(f"shuffle kv with combiner:    {shuffle_with_combiner}")
print(f"reduction ratio: {shuffle_no_combiner/shuffle_with_combiner:.2f}x")
print(f"final counts unchanged: hello=4 world=3 bigdata=3")
